#include <datamunge/optim/levenberg_marquardt.hpp>
#include <cmath>
#include <stdexcept>
namespace datamunge::optim { namespace { double val(const std::vector<double>& r){double s=0;for(double x:r)s+=.5*x*x;return s;} } LevenbergMarquardt::LevenbergMarquardt(LevenbergMarquardtOptions o):options_(o){} double LevenbergMarquardt::optimize(ResidualFunction& f,std::vector<double>& x)const{if(options_.initial_damping<=0)throw std::invalid_argument("LevenbergMarquardt: initial_damping must be positive");double d=options_.initial_damping;auto r=f.residuals(x);double v=val(r);for(std::size_t it=0;it<options_.max_iterations;++it){auto j=f.jacobian(x);std::vector<std::vector<double>> a(x.size(),std::vector<double>(x.size()));std::vector<double>b(x.size());for(std::size_t k=0;k<r.size();++k)for(std::size_t p=0;p<x.size();++p){b[p]-=j[k][p]*r[k];for(std::size_t q=0;q<x.size();++q)a[p][q]+=j[k][p]*j[k][q];}for(std::size_t p=0;p<x.size();++p)a[p][p]+=d;for(std::size_t p=0;p<x.size();++p){for(std::size_t q=p+1;q<x.size();++q){double z=a[q][p]/a[p][p];for(std::size_t c=p;c<x.size();++c)a[q][c]-=z*a[p][c];b[q]-=z*b[p];}}for(std::size_t p=x.size();p-->0;){for(std::size_t q=p+1;q<x.size();++q)b[p]-=a[p][q]*b[q];b[p]/=a[p][p];}std::vector<double> y=x;double n=0;for(std::size_t p=0;p<x.size();++p){y[p]+=b[p];n+=b[p]*b[p];}auto nr=f.residuals(y);double nv=val(nr);if(nv<v){x=std::move(y);r=std::move(nr);v=nv;d*=.3;}else d*=10;if(std::sqrt(n)<=options_.tolerance)break;}return v;}}
